<a href="#" class="wa-float wa-general" aria-label="Pedir por WhatsApp"><span class="wa-icon">✆</span><span>Pedir por WhatsApp</span></a>
<div class="overlay" id="overlay"><aside class="cart"><div class="cart__head"><h3>Tu pedido</h3><button class="close" id="close-cart">✕</button></div><div class="cart__lines" id="cart-lines"></div><div class="cart__foot"><div class="cart-total"><span>Total</span><span id="cart-total">Bs 0,00</span></div><a id="send-order" class="order" href="#" target="_blank">Enviar pedido por WhatsApp</a></div></aside></div>
<script>
const PRODUCTS = @json($productData);
const PHONE = @json($phone);
const COMPANY = @json($companyName);
const byId = id => PRODUCTS.find(product => product.id === Number(id));
const cart = {};
const money = value => Number(value || 0).toLocaleString('es-BO',{minimumFractionDigits:2,maximumFractionDigits:2});
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[character]));
const whatsapp = text => PHONE ? `https://wa.me/${PHONE}?text=${encodeURIComponent(text)}` : `https://wa.me/?text=${encodeURIComponent(text)}`;
function updateCart(){
    const lines = Object.entries(cart).map(([id,qty]) => ({...byId(id),qty})).filter(line => line.id);
    const total = lines.reduce((sum,line) => sum + line.price * line.qty,0);
    document.getElementById('cart-count').textContent = lines.reduce((sum,line) => sum + line.qty,0);
    document.getElementById('cart-total').textContent = `Bs ${money(total)}`;
    document.getElementById('cart-lines').innerHTML = lines.length ? lines.map(line => `<div class="cart-line">${line.image?`<img src="${escapeHtml(line.image)}" alt="">`:'<div>📦</div>'}<div><strong>${escapeHtml(line.name)}</strong><div class="muted">Bs ${money(line.price)}</div></div><div class="qty"><button data-dec="${line.id}">−</button><b>${line.qty}</b><button data-inc="${line.id}">+</button></div></div>`).join('') : '<p class="muted">Tu carrito está vacío.</p>';
    const detail = lines.map(line => `• ${line.qty} x ${line.name} — Bs ${money(line.price * line.qty)}`).join('\n');
    document.getElementById('send-order').href = whatsapp(lines.length ? `¡Hola ${COMPANY}! Quiero realizar este pedido:\n\n${detail}\n\nTotal aproximado: Bs ${money(total)}\n\n¿Me confirman stock y entrega?` : `¡Hola ${COMPANY}! Quiero consultar sus productos.`);
}
document.addEventListener('click', event => {
    const add = event.target.closest('[data-add]'); if(add){const p=byId(add.dataset.add);if(p&&p.stock>0){cart[p.id]=(cart[p.id]||0)+1;updateCart();document.getElementById('overlay').classList.add('open')}return}
    const inc=event.target.closest('[data-inc]');if(inc){cart[inc.dataset.inc]++;updateCart();return}
    const dec=event.target.closest('[data-dec]');if(dec){cart[dec.dataset.dec]--;if(cart[dec.dataset.dec]<=0)delete cart[dec.dataset.dec];updateCart();return}
    const chip=event.target.closest('.chip');if(chip){document.querySelectorAll('.chip').forEach(c=>c.classList.remove('active'));chip.classList.add('active');filterProducts()}
});
const overlay=document.getElementById('overlay');document.getElementById('open-cart').onclick=()=>overlay.classList.add('open');document.getElementById('close-cart').onclick=()=>overlay.classList.remove('open');overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.classList.remove('open')});
function filterProducts(){const query=document.getElementById('search').value.trim().toLocaleLowerCase('es');const category=document.querySelector('.chip.active')?.dataset.category||'Todos';let visible=0;document.querySelectorAll('.catalog-product').forEach(card=>{const show=(!query||card.dataset.name.includes(query))&&(category==='Todos'||card.dataset.category===category);card.style.display=show?'flex':'none';if(show)visible++});document.getElementById('result-count').textContent=`${visible} ${visible===1?'producto':'productos'}`;document.getElementById('empty').style.display=visible?'none':'block'}
document.getElementById('search').addEventListener('input',filterProducts);document.querySelectorAll('.wa-general').forEach(link=>link.href=whatsapp(`¡Hola ${COMPANY}! Vi su catálogo web y quiero consultar precios.`));updateCart();
</script>
</body></html>
